WITH v AS (INSERT INTO project_plan_versions (project_id, id) VALUES ($1, 'v-probe-9990') RETURNING id), m AS (INSERT INTO project_plan_milestones (project_id, id, version_id, ord, title) SELECT $1, 'M9990', v.id, 9990, 'проба самотеста' FROM v RETURNING id), t AS (INSERT INTO project_plan_tasks (project_id, id, milestone_id, ord, title, size, state, kind) SELECT $1, 'M9990-T1', m.id, 1, 'проба самотеста', 'S', 'closed', 'dev' FROM m RETURNING id), q AS (INSERT INTO project_requirements (project_id, id, kind, area, text, satisfied, title) VALUES ($1, 'FR-PROBE-9990', 'FR', 'проба', 'проба самотеста', false, 'проба самотеста') RETURNING id), l AS (INSERT INTO task_requirement (project_id, task_id, requirement_id) SELECT $1, t.id, q.id FROM t, q RETURNING task_id) INSERT INTO entity_stamp (project_id, kind, id, text_hash, created_at, updated_at) SELECT $1, 'task', t.id, 'probe-selftest', ((extract(epoch from now()) * 1000)::bigint - 172800000), ((extract(epoch from now()) * 1000)::bigint - 172800000) FROM t UNION ALL SELECT $1, 'requirement', q.id, 'probe-selftest', ((extract(epoch from now()) * 1000)::bigint - 172800000), (extract(epoch from now()) * 1000)::bigint FROM q
